import React, { useState } from 'react';
import axios from 'axios';

const API_BASE = process.env.REACT_APP_API_BASE || 'http://localhost:8001/api';

export default function EnrollmentPage() {
  const [sessionToken, setSessionToken] = useState('');
  const [enrollmentStatus, setEnrollmentStatus] = useState(null);
  const [isEnrolling, setIsEnrolling] = useState(false);
  const [error, setError] = useState('');
  const userId = localStorage.getItem('user_id');

  const startEnrollment = async () => {
    if (!userId) {
      setError('User is not logged in. Please log in first.');
      return;
    }

    try {
      const response = await axios.post(`${API_BASE}/enrollment/start`, {
        user_id: parseInt(userId, 10)
      });
      setSessionToken(response.data.session_token);
      setEnrollmentStatus({
        samples_collected: 0,
        target_samples: response.data.target_samples
      });
      setError('');
      setIsEnrolling(true);
    } catch (err) {
      const message = err.response?.data?.detail || err.response?.data?.message || err.message;
      setError(`Failed to start enrollment: ${message}`);
    }
  };

  const captureData = async () => {
    // Simulated biometric data capture
    const keystrokeData = {
      dwell_times: Array.from({ length: 10 }, () => Math.random() * 200),
      flight_times: Array.from({ length: 9 }, () => Math.random() * 100)
    };

    try {
      await axios.post(`${API_BASE}/enrollment/capture`, {
        user_id: parseInt(userId),
        event_type: 'keystroke',
        features: keystrokeData,
        session_token: sessionToken
      });

      // Update status
      const statusResponse = await axios.get(
        `${API_BASE}/enrollment/status/${sessionToken}`
      );
      setEnrollmentStatus(statusResponse.data);

      if (statusResponse.data.enrollment_complete) {
        completeEnrollment();
      }
    } catch (err) {
      setError('Failed to capture data');
    }
  };

  const completeEnrollment = async () => {
    try {
      await axios.post(`${API_BASE}/enrollment/complete`, {
        session_token: sessionToken,
        user_id: parseInt(userId)
      });
      alert('Enrollment completed successfully!');
      setIsEnrolling(false);
    } catch (err) {
      setError('Failed to complete enrollment');
    }
  };

  return (
    <div style={styles.container}>
      <h1>Biometric Enrollment</h1>

      {!isEnrolling ? (
        <button onClick={startEnrollment} style={styles.button}>
          Start Enrollment
        </button>
      ) : (
        <div style={styles.enrollmentBox}>
          <h2>Enrollment in Progress</h2>
          <p>
            Samples: {enrollmentStatus?.samples_collected} / {enrollmentStatus?.target_samples}
          </p>
          <div style={styles.progressBar}>
            <div
              style={{
                ...styles.progressFill,
                width: `${(enrollmentStatus?.samples_collected / enrollmentStatus?.target_samples) * 100}%`
              }}
            />
          </div>

          <button onClick={captureData} style={styles.button}>
            Capture Biometric Data
          </button>

          {enrollmentStatus?.samples_collected >= enrollmentStatus?.target_samples && (
            <button onClick={completeEnrollment} style={styles.buttonSuccess}>
              Complete Enrollment
            </button>
          )}
        </div>
      )}

      {error && <div style={styles.error}>{error}</div>}
    </div>
  );
}

const styles = {
  container: {
    padding: '40px',
    maxWidth: '600px',
    margin: '0 auto'
  },
  button: {
    padding: '10px 20px',
    backgroundColor: '#007bff',
    color: 'white',
    border: 'none',
    borderRadius: '4px',
    cursor: 'pointer',
    fontSize: '16px',
    marginTop: '10px'
  },
  buttonSuccess: {
    padding: '10px 20px',
    backgroundColor: '#28a745',
    color: 'white',
    border: 'none',
    borderRadius: '4px',
    cursor: 'pointer',
    fontSize: '16px',
    marginTop: '10px'
  },
  enrollmentBox: {
    border: '1px solid #ddd',
    padding: '20px',
    borderRadius: '4px',
    backgroundColor: '#f9f9f9'
  },
  progressBar: {
    width: '100%',
    height: '20px',
    backgroundColor: '#e0e0e0',
    borderRadius: '10px',
    overflow: 'hidden',
    marginTop: '10px'
  },
  progressFill: {
    height: '100%',
    backgroundColor: '#4caf50',
    transition: 'width 0.3s'
  },
  error: {
    color: '#d32f2f',
    marginTop: '20px',
    padding: '10px',
    backgroundColor: '#ffebee',
    borderRadius: '4px'
  }
};
